// Mirrors scripts/test-all-services.sh. optional: the host may be powered
// off (laptops, desktop, VM), so unreachable is reported but never alerted.
const http = require('http');
const net = require('net');

const TIMEOUT_MS = 5000;

const checks = [
  { host: 'mnemosyne', name: 'SSH', port: 22 },
  { host: 'mnemosyne', name: 'Jellyfin', port: 8096, path: '/health', expect: /Healthy/ },
  { host: 'mnemosyne', name: 'Forgejo', port: 3000, path: '/api/healthz', expect: /"status":\s*"pass"/ },
  { host: 'mnemosyne', name: 'transmission-webUi', port: 4173, path: '/' },
  { host: 'mnemosyne', name: 'yt-dlp-webUi', port: 4174, path: '/' },
  { host: 'mnemosyne', name: 'git-dashboard', port: 3004, path: '/health' },
  { host: 'mnemosyne', name: 'backup-health', port: 3005, path: '/health' },
  { host: 'mnemosyne', name: 'Dockhand', port: 3006, path: '/' },
  { host: 'mnemosyne', name: 'Homepage', port: 8082, path: '/' },

  { host: 'hermes', name: 'SSH', port: 22 },
  { host: 'hermes', name: 'Transmission', port: 9091, path: '/transmission/web/' },
  { host: 'hermes', name: 'transmission-API', port: 3002, path: '/health', expect: /"status":\s*"ok"/ },
  { host: 'hermes', name: 'yt-dlp-API', port: 3003, path: '/health' },

  { host: 'athena', name: 'SSH', port: 22 },
  { host: 'athena', name: 'Ollama', port: 11434, path: '/', expect: /Ollama is running/ },
  { host: 'athena', name: 'Open WebUI', port: 8080, path: '/health' },
  { host: 'athena', name: 'SearXNG', port: 8888, path: '/' },
  { host: 'athena', name: 'openwebui-usage', port: 3007, path: '/health' },

  { host: 'proteus', name: 'SSH', port: 22, optional: true },
  { host: 'janus', name: 'SSH', port: 22, optional: true },
  { host: 'janus-vm', name: 'SSH', port: 22, optional: true },
  { host: 'echo', name: 'SSH', port: 22, optional: true },
];

function tcpCheck(c) {
  return new Promise((resolve) => {
    const sock = net.connect({ host: c.host, port: c.port });
    const done = (ok, detail) => { sock.destroy(); resolve({ ok, detail }); };
    sock.setTimeout(TIMEOUT_MS, () => done(false, 'timeout'));
    sock.once('connect', () => done(true, 'port open'));
    sock.once('error', (e) => done(false, e.code || e.message));
  });
}

// Any status under 500 counts as up (UIs that redirect or answer 401),
// unless the check gives a pattern the body must match.
function httpCheck(c) {
  return new Promise((resolve) => {
    const req = http.get({ host: c.host, port: c.port, path: c.path, timeout: TIMEOUT_MS }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (d) => { if (body.length < 65536) body += d; });
      res.on('end', () => {
        const status = res.statusCode;
        if (status >= 500) return resolve({ ok: false, detail: `HTTP ${status}` });
        if (c.expect && !c.expect.test(body)) {
          return resolve({ ok: false, detail: `HTTP ${status}, body does not match ${c.expect}` });
        }
        resolve({ ok: true, detail: `HTTP ${status}` });
      });
    });
    req.on('timeout', () => req.destroy(new Error('timeout')));
    req.on('error', (e) => resolve({ ok: false, detail: e.code || e.message }));
  });
}

const results = await Promise.all(checks.map(async (c) => {
  const start = Date.now();
  const r = c.path === undefined ? await tcpCheck(c) : await httpCheck(c);
  return {
    json: {
      host: c.host,
      service: c.name,
      target: `${c.host}:${c.port}${c.path ?? ''}`,
      ok: r.ok,
      optional: !!c.optional,
      detail: r.detail,
      ms: Date.now() - start,
    },
  };
}));

return results;

// Alerts only when the set of failures changes (new failure or recovery),
// not on every run. Static data persists only in production (active) runs.
const items = $input.all().map((i) => i.json);
const failed = items.filter((r) => !r.ok && !r.optional);
const offline = items.filter((r) => !r.ok && r.optional);
const line = (r) => `- ${r.host} ${r.service} (${r.target}): ${r.detail}`;

const state = $getWorkflowStaticData('global');
const key = failed.map((r) => `${r.host}/${r.service}`).sort().join(',');
const changed = (state.lastFailures ?? '') !== key;
state.lastFailures = key;

let message;
if (failed.length) {
  message = `Homelab health: ${failed.length} check(s) FAILING\n` + failed.map(line).join('\n');
} else {
  message = `Homelab health: all ${items.length - offline.length} checks OK`;
}
if (offline.length) {
  message += `\nOffline (optional): ${offline.map((r) => r.host).join(', ')}`;
}

const webhookUrl = $('Config').first().json.webhookUrl;

return [{
  json: {
    status: failed.length ? 'fail' : 'ok',
    passed: items.filter((r) => r.ok).length,
    failed: failed.length,
    offline: offline.map((r) => r.host),
    total: items.length,
    message,
    notify: changed && !!webhookUrl,
    results: items,
  },
}];
